insert into geo_lookup_tables (id, table_name, description, value_type)
values
  ('80676e7c-7723-588f-a751-0caffe1abd59', 'in_80ami_2026', 'HUD FY2026 low-income limit (80% of area median income), effective June 1, 2026, from IHCDA RED Notice 26-17. Marion, Hamilton and Hendricks share the Indianapolis-Carmel-Anderson metro limits, so all three are identical; Marion matches the City of Indianapolis repair page.', 'income_limit'),
  ('07d6a432-eb68-5267-b67f-2d0aea256ee9', 'in_50ami_2026', 'HUD FY2026 very low-income limit (50% of area median income), effective June 1, 2026, from IHCDA RED Notice 26-17. Marion, Hamilton and Hendricks are identical (same metro). Loaded ahead of need: no program rule uses it yet.', 'income_limit'),
  ('fdef93f4-72f6-5d81-8478-1b782091770a', 'in_30ami_2026', 'HUD FY2026 extremely low-income limit (30% of area median income), effective June 1, 2026, from IHCDA RED Notice 26-17. Marion, Hamilton and Hendricks are identical (same metro). Loaded ahead of need: no program rule uses it yet.', 'income_limit'),
  ('88c37b1f-4cc0-57d9-929c-6d3f356eb301', 'fpl_150_2026', '150% of the 2026 HHS poverty guidelines (48 contiguous states), effective January 13, 2026. Household sizes 1-8; larger households use the 8-person figure, which understates their limit.', 'income_limit'),
  ('a8fd73ca-c0f8-5dbb-837b-ad1305e2e0ab', 'fpl_200_2026', '200% of the 2026 HHS poverty guidelines (48 contiguous states), effective January 13, 2026. Household sizes 1-8; larger households use the 8-person figure, which understates their limit.', 'income_limit'),
  ('a5742d39-5a1f-5bb3-9b17-c9e65fb5c0be', 'in_usda_very_low', 'USDA Section 504 very-low income limits by county. Not loaded yet: the engine reports this as something USDA confirms.', 'income_limit'),
  ('e19a084f-b8b0-5c44-b10e-c9ea475ae5b3', 'in_usda_low', 'USDA Section 504 low income limits by county. Not loaded yet: the engine reports this as something USDA confirms.', 'income_limit')
