insert into programs (id, slug, name, administering_entity, reach, program_type, description, benefit_summary, max_amount, strings_attached, how_to_apply, call_script, source_url, funding_status, status_note, reopens_note, is_emergency_route, open_questions, last_verified_date)
values
  ('31023004-be64-554c-9a51-07d4f013357c', 'usda-504-grant', 'USDA Section 504 Home Repair Grant', 'USDA Rural Development', 'federal', 'grant', 'Grant for very-low-income homeowners age 62 or older in USDA-eligible rural areas, to remove health and safety hazards.', 'Up to $10,000 lifetime grant ($15,000 in a presidentially declared disaster area). Can be combined with the 504 loan for up to $50,000.', 10000, 'Repaid if the home is sold within 3 years. The homeowner must be unable to get affordable credit elsewhere.', 'Call the USDA Rural Development office for the county. Ask for Form RD 3550-35 (intake) and RD 3550-1 (authorization to release information).', 'I''m calling for a homeowner age {age} in {county} County who owns and lives in the home. They have {repair} and can''t afford the repair. Can you confirm the address is USDA-eligible and send the Section 504 grant intake form?', 'https://www.rd.usda.gov/programs-services/single-family-housing-programs/single-family-housing-repair-loans-grants/in', 'open', 'Applications accepted year-round; approval time depends on local funding.', null, false, '{}'::text[], '2026-10-08'),
  ('2ab92cdf-8f06-5335-9553-6f8cf3db775c', 'usda-504-loan', 'USDA Section 504 Home Repair Loan', 'USDA Rural Development', 'federal', 'low_interest_loan', '1% fixed-rate repair loan for low- and very-low-income homeowners in USDA-eligible rural areas who cannot get affordable credit elsewhere.', 'Up to $40,000 at 1% fixed for 20 years. Can be combined with the 504 grant for up to $50,000.', 40000, 'This is a loan with monthly payments. Full title service is required if 504 loans total more than $25,000.', 'Call the USDA Rural Development office for the county; the same intake covers the grant and the loan.', 'I''m calling for a homeowner in {county} County who owns and lives in the home and needs help with {repair}. They can''t get a regular loan. Can you check whether the address is USDA-eligible and whether a Section 504 loan, or a grant and loan together, could work?', 'https://www.rd.usda.gov/programs-services/single-family-housing-programs/single-family-housing-repair-loans-grants/in', 'open', 'Applications accepted year-round.', null, false, '{}'::text[], '2026-10-08'),
  ('eb54db11-f9f7-5395-a7fc-37cd6000c80e', 'va-hisa', 'VA Home Improvements and Structural Alterations (HISA)', 'U.S. Department of Veterans Affairs', 'federal', 'grant', 'Medically necessary access changes to a veteran''s home: entry ramps, bathroom access, lowered counters and sinks.', 'Lifetime benefit of $6,800 for a service-connected condition or a 50%+ rating; $2,000 otherwise.', 6800, 'Does not pay for roofs, furnaces, air conditioning or routine repairs. Needs a VA physician''s prescription.', 'Ask the veteran''s VA doctor for a prescription, then submit VA Form 10-0103 with an itemized estimate and a photo of the area to the Prosthetic and Sensory Aids Service.', 'I''m helping a veteran who needs help with {repair} at home to get in and out safely. How do we get a HISA prescription and submit Form 10-0103?', 'https://www.prosthetics.va.gov/psas/HISA2.asp', 'open', 'Lifetime benefit; ask PSAS how much of it the veteran has already used.', null, false, '{}'::text[], '2026-10-08'),
  ('4f0df00b-70d0-5e86-9988-7c8de7c0fda1', 'va-sah-sha', 'VA Specially Adapted Housing and Special Home Adaptation grants', 'U.S. Department of Veterans Affairs', 'federal', 'grant', 'Grants to adapt a home for veterans with specific severe service-connected disabilities.', 'Up to $126,526 (SAH) or $25,350 (SHA) at fiscal 2026 rates; usable up to six times.', 126526, 'Only for specific disabilities, such as loss of use of limbs, blindness in both eyes, severe burns or certain respiratory injuries.', 'Apply online with VA Form 26-4555, by mail or in person.', 'I''m helping a veteran with a service-connected disability who needs help with {repair}. Can you tell us whether their rating qualifies for a Specially Adapted Housing or Special Home Adaptation grant?', 'https://www.va.gov/housing-assistance/disability-housing-grants/', 'open', 'Amounts are for fiscal 2026 (to September 30, 2026); check for fiscal 2027 figures.', null, false, array['Fiscal 2027 grant amounts']::text[], '2026-10-08'),
  ('66e2821e-8a1b-5a29-bedc-209de649b79a', 'pathways-home-mod', 'Indiana PathWays for Aging waiver: home modifications', 'Indiana FSSA, through the Area Agency on Aging', 'state', 'free_service', 'Medicaid waiver service paying for medically necessary accessibility changes for people 60 and older on Medicaid.', 'Up to $20,000 lifetime, plus $1,000 a year for repairs. Covers ramps, lifts, wider doorways, and bathroom and kitchen changes.', 20000, 'Basic, medically necessary work only; no upgrades. Two bids needed for work over $5,000.', 'Call the Area Agency on Aging, which assesses eligibility for the waiver.', 'I''m calling for a homeowner age {age} on Medicaid who needs help with {repair} to stay safely at home. Can you assess them for PathWays waiver home modifications?', 'https://in.gov/fssa/ompp/files/Home-Modification.pdf', 'open', 'Waiver waitlists may apply.', null, false, '{}'::text[], '2026-10-08'),
  ('6be7e3fe-fa47-5524-86f4-3fda813bd2c7', 'cicoa-home-mods', 'CICOA home accessibility modifications', 'CICOA Aging & In-Home Solutions', 'nonprofit', 'free_service', 'Area Agency on Aging for central Indiana; assesses the home and matches a funding source for safety and accessibility changes.', 'Grab bars, handrails, wheelchair ramps, wider doorways, lever handles and similar changes.', null, 'Depends on the funding source CICOA matches.', 'Call the Aging & Disability Resource Center for a home assessment. The homeowner should be on the call to consent.', 'I''m calling with {name}, a homeowner age {age} in {county} County, who needs help with {repair}. They''re on the line to consent. Can we schedule a home safety assessment?', 'https://cicoa.org/services/home-accessibility-modifications/', 'open', 'Funding is limited, per the City of Indianapolis.', null, false, '{}'::text[], '2026-10-08'),
  ('0321db90-0984-5580-a59b-44dd7999f0ca', 'cicoa-oahmp', 'CICOA Older Americans Home Modification Program', 'CICOA Aging & In-Home Solutions (HUD-funded)', 'nonprofit', 'free_service', 'HUD-funded small safety fixes for homeowners age 62 and older.', 'Grab bars, handrails, lighting, comfort-height toilets, modular ramps, gutter repair and similar small fixes.', null, 'Small fixes only. Excludes roofs, new furnaces, permanent ramps, door widening, walk-in showers and major rewiring.', 'Complete CICOA''s online application.', 'I''m helping {name}, age {age}, who owns and lives in their home and needs help with {repair}. What is the income limit for the Older Americans Home Modification Program, and can we apply?', 'https://cicoa.org/services/home-accessibility-modifications/', 'open', null, null, false, array['What is the income limit?']::text[], '2026-10-08'),
  ('bed8209e-2474-52fa-880a-48de8f745491', 'cagi-weatherization', 'Weatherization Assistance Program (CAGI)', 'Community Action of Greater Indianapolis (IHCDA program)', 'nonprofit', 'free_service', 'Free energy audit and efficiency work; can repair or replace an unsafe furnace or water heater.', 'Insulation, air and duct sealing, and furnace or water heater repair or replacement where testing calls for it.', null, 'Homes weatherized before through this program may not qualify again.', 'Apply through CAGI''s online portal or call the weatherization office.', 'I''m calling for a homeowner in {county} County who has {repair}. Their household income is about ${income} for a household of {size}. Can they apply for weatherization?', 'https://cagi-in.org/weatherization/', 'open', null, null, false, '{}'::text[], '2026-10-08'),
  ('4667fe19-5e55-57ba-b02c-916650ac1ff4', 'indianapolis-hrp', 'City of Indianapolis Homeowner Repair Program', 'City of Indianapolis, Department of Metropolitan Development', 'city', 'forgivable_loan', 'Critical home repairs and accessibility changes for income-qualified owners inside the City of Indianapolis.', 'Roofs, windows, siding, furnaces, air conditioning, plumbing, electrical and accessibility, at no upfront cost.', null, '30-year forgivable lien, no payments and no interest. Repaid from sale proceeds if sold sooner; an heir who lives in the home can finish the term. City contractors only; every home is tested for radon.', 'Pre-screen application linked from the city''s program page.', 'I''m calling for a homeowner inside Indianapolis who needs help with {repair}. When do non-emergency applications reopen, and can we get on a notification list?', 'https://www.indy.gov/activity/home-repair-program', 'closed', 'Closed to new non-emergency applications.', 'Expected to reopen in 2027 (city page, October 2026). Emergencies still considered: see the SEND emergency route.', false, array['Reopening date for 2027']::text[], '2026-10-08'),
  ('79f0027c-a8a9-5713-b271-130e1f5f3d29', 'send-emergency', 'Indianapolis emergency home repair (City program through SEND)', 'City of Indianapolis, with Southeast Neighborhood Development (SEND)', 'city', 'forgivable_loan', 'Emergency health and safety repairs for owners inside the City of Indianapolis. The city takes the application and forwards emergencies to SEND.', 'No heat in winter, sewage backup, no water, electrical arcing.', null, 'Same 30-year forgivable lien as the city program; no payments or interest.', 'Email or call the city''s Homeowner Repair team and say it is an emergency.', 'This is an emergency: a homeowner inside Indianapolis has {repair}. They own and live in the home and their property taxes are current. Can this go to SEND as an emergency repair?', 'https://www.sendcdc.org/home-repair', 'open', 'Emergency applications still considered while the main city program is closed.', null, true, '{}'::text[], '2026-10-08'),
  ('2e1cf11d-007b-5110-b9c0-490b4a064dbb', 'hrg-home-repair', 'Home Repairs for Good: Home Repair Program', 'Home Repairs for Good', 'nonprofit', 'free_service', 'Free critical repairs for low-income homeowners 62 and older or with a disability in Marion County, mostly by volunteers.', 'Handrails, grab bars, ramps, furnace repair or replacement, plumbing, water heaters, small roof and electrical repairs, gutters, siding.', null, 'None stated.', 'Call to request a repair.', 'I''m calling for {name}, age {age}, who owns their home in Marion County and needs help with {repair}. Their household income is about ${income} a year for a household of {size}. Which addresses do you serve, and which year''s income limits apply?', 'https://www.homerepairsforgood.org/home-repair-program', 'open', null, null, false, array['Which Marion County addresses get the full repair list?', 'Which year''s income limits apply? (posted chart uses 2023 figures)']::text[], '2026-10-08'),
  ('3c5f32ab-2e47-5195-b76f-b53bd74560f1', 'hrg-home-stabilization', 'Home Repairs for Good: Home Stabilization Program', 'Home Repairs for Good', 'nonprofit', 'free_service', 'Larger repairs for a small number of homes each year, layered with other programs where possible.', 'Jobs over $5,000, averaging about $15,000: roof replacement, sewer replacement, major plumbing or electrical work.', null, 'None stated. Limited by available funding.', 'Call to request services.', 'I''m calling for {name}, age {age}, in Marion County, who needs help with {repair}, a larger job. Could the Home Stabilization Program take it on, and is the address in your focus area?', 'https://www.homerepairsforgood.org/home-stabilization-program', 'open', 'Limited by available funding.', null, false, array['Is the address inside the focus area?', 'Which year''s income limits apply?']::text[], '2026-10-08'),
  ('6ccfcae3-f8da-5fcd-893a-42494e998a5e', 'rebuilding-together-indy', 'Rebuilding Together Indianapolis', 'Rebuilding Together Indianapolis', 'nonprofit', 'free_service', 'Free volunteer repairs for low-income, older or disabled homeowners in one selected neighborhood each cycle.', 'Accessibility, safety, exterior, weatherization and general repairs around Rebuild Day (next: April 24, 2027).', null, 'Not every applicant is selected.', 'Online homeowner application, email, or mail to 6510 Telecom Dr, Suite 200, Indianapolis, IN 46278.', 'I''m helping a homeowner in {county} County who needs help with {repair}. Is their address inside your current neighborhood, and is the application open?', 'https://www.rebuildingtogetherindy.org/who-we-serve', 'open', 'Annual cycle tied to Rebuild Day.', null, false, '{}'::text[], '2026-10-08'),
  ('57923c1e-f925-5f5d-9e8b-a19bec1adefd', 'englewood-cdc', 'Englewood CDC owner-occupied repair', 'Englewood Community Development Corporation', 'nonprofit', 'free_service', 'Repairs for low-income east-side owners with deferred maintenance or dangerous conditions.', 'Health, safety, accessibility and essential-system repairs.', null, 'Lien or cost terms not stated: ask.', 'Fill out the intake form on their site.', 'I''m calling for a homeowner in ZIP {zip} who needs help with {repair}. Is there a lien, and are you taking applications now?', 'https://englewoodcdc.com/our-work/affordable-housing/ownership-and-repairs/', 'unknown', 'The page says it ''has opportunities'' but not whether applications are open.', null, false, array['Is a lien placed on the home?', 'Are applications open now?']::text[], '2026-10-08'),
  ('b3393c4b-6d3d-5ed9-81d4-ae7b55662677', 'saws-ramps', 'Servants at Work (SAWs) wheelchair ramps', 'Servants at Work, Inc.', 'nonprofit', 'free_service', 'Free custom wooden access ramps for low-income households with a permanent mobility need.', 'A new ramp built to ADA standards, usually installed in 4 to 6 hours.', null, 'One ramp per person in a lifetime. SAWs doesn''t repair or remove other ramps. Approved applicants wait on a list.', 'Online ramp application; an agency or case manager can apply on the person''s behalf.', 'I''m applying on behalf of {name} in {county} County, who has a permanent need for a ramp. Household income is about ${income} a year for a household of {size}.', 'https://www.sawsramps.org/apply-for-ramp-az-in-nv/', 'open', 'No published wait time.', null, false, '{}'::text[], '2026-10-08'),
  ('ebe51f78-6a85-5f53-9a50-ceeaace0077c', 'fhlbi-revive', 'FHLBank Indianapolis Revive home repair grant', 'Federal Home Loan Bank of Indianapolis, through member banks', 'state', 'grant', 'Annual grant for deferred maintenance and accessibility, applied for through a participating member bank or credit union.', 'Up to $15,000 (member bank''s 2025 terms), no repayment. Roofs, HVAC, water heaters, windows, siding, ramps, grab bars and more.', 15000, 'The homeowner names the contractor and supplies two itemized bids; payment is by checks made out to homeowner and contractor together. No second grant on the same property within 5 years.', 'Through a participating member bank or credit union when the round opens. FHLBank does not deal with households.', 'I''m helping a homeowner in {county} County who needs help with {repair}. Will you take Revive home repair grant applications for Marion County in 2027, and when does the round open?', 'https://www.fhlbi.com/services/community-programs/revive-home-repair-grant/', 'closed', '2026 funds exhausted.', 'Annual round; a member bank says check back in early 2027.', false, array['Which member bank takes Marion County applications in 2027?']::text[], '2026-10-08'),
  ('89e29396-5dbd-506b-90d7-0716ba1745bb', 'indiana-energy-saver', 'Indiana Energy Saver Program (home energy rebates)', 'Indiana Office of Energy Development', 'state', 'rebate', 'Discounts on energy-efficiency upgrades installed by a qualified contractor.', 'Below 80% of area median income, the state plan gives 80% of a whole-home project up to $4,000 or $8,000, and 100% of heat-pump, appliance and wiring costs up to $14,000.', 14000, 'Don''t start work before approval: work begun outside the program is not rebated. Amounts come from the state''s planning presentation and need confirming.', 'Register on the portal and complete the pre-screening.', 'I''m helping a homeowner who has {repair} and may need new equipment. Household income is about ${income} for a household of {size}. Which rebate tier applies, and what are the current amounts?', 'https://portal.indianaenergysaver.com/en-US/', 'open', 'Taking pre-screenings.', null, false, array['Are the rebate amounts in the state plan the ones in force?']::text[], '2026-10-08'),
  ('14b56fbf-70ca-5314-9adf-0447ae155052', 'inhp-repair-loan', 'INHP home repair loan', 'Indianapolis Neighborhood Housing Partnership', 'nonprofit', 'low_interest_loan', 'Repair loans for Marion County owner-occupants; earlier rounds were interest-free for seniors.', 'Repair loan; terms depend on the funding source.', null, 'A loan, when available.', 'Register on INHP''s site when the program returns.', 'Is the INHP home repair loan program open again?', 'https://www.inhp.org/home-repair-loans/eligibility', 'closed', 'Suspended: funds exhausted.', 'INHP says check back in 2027.', false, '{}'::text[], '2026-10-08'),
  ('53c9f5e2-d818-5128-a9a3-fbc6b0105f04', 'township-trustee', 'Township trustee emergency assistance', 'The township trustee for the client''s township', 'county', 'referral', 'Every Indiana township must provide emergency assistance, which can include housing and utility help.', 'Varies by township.', null, 'Each township sets its own rules.', 'Call the trustee''s office for the client''s township.', 'I''m calling for a homeowner in {township} Township who has an urgent repair: {repair}. What emergency assistance can the trustee provide?', 'https://liheapch.ncat.org/node/1231', 'unknown', 'Not published; varies by township.', null, true, array['What will this township cover?']::text[], '2026-10-08'),
  ('594d45a3-2e65-5def-8f95-643251a0a9cb', 'ihcda-ramp-up', 'Ramp Up Indiana', 'IHCDA, through local nonprofit grantees', 'state', 'free_service', 'IHCDA grants to local nonprofits and governments to build exterior ramps for owner-occupants.', 'One exterior ramp.', null, 'Exterior ramps only.', 'Through the local grantee; ask IHCDA which nonprofit serves the county.', 'Which nonprofit holds a Ramp Up Indiana grant for {county} County?', 'https://www.in.gov/ihcda/program-partners/ramp-up-indiana/', 'unknown', 'Program active (forms revised January 2026); grantee list not published.', null, false, array['Which nonprofits hold a grant for Marion, Hendricks and Hamilton counties?']::text[], '2026-10-08'),
  ('0d6551da-37e9-5048-af30-4ba1b21e01b5', 'ocra-oor', 'Owner-Occupied Rehabilitation (OCRA block grant)', 'Indiana Office of Community and Rural Affairs, through local governments', 'state', 'free_service', 'State block grants to smaller cities and counties to run local home repair programs.', 'Up to $25,000 per home for roofs, heating and cooling, water heaters, electrical and accessibility.', 25000, 'Restrictive covenant on the home; term set by the local program.', 'Through the local government running a funded program.', 'Does {county} County, or the client''s town, have a current Owner-Occupied Rehabilitation award, and who runs intake?', 'https://www.in.gov/ocra/cdbg/owner-occupied-rehabilitation-program', 'unknown', 'No published list of funded communities.', null, false, array['Does this community hold a current award?']::text[], '2026-10-08')
