  ('61d28c44-f7b3-53f3-aceb-aeafd6ca6cff', '31023004-be64-554c-9a51-07d4f013357c', 'geographic_scope'::rule_type, '{"scope_level": "state", "allowed_values": ["IN"]}'::jsonb, 'Home is in Indiana', 0),
