  ('68df8566-df47-50b3-acdf-7ba96f4c062b', '2ab92cdf-8f06-5335-9553-6f8cf3db775c', 'repair_type'::rule_type, '{"allowed": ["roof", "heating", "cooling", "water_heater", "plumbing_sewer", "septic_well", "electrical", "structural", "windows_doors", "insulation_weatherization", "ramp", "accessibility", "safety_fixes", "lead_mold", "storm_damage", "other"]}'::jsonb, 'Repair, improvement or hazard removal', 5),
