  ('9ccc6808-dbcc-5f29-9600-1fe51cdcd066', 'eb54db11-f9f7-5395-a7fc-37cd6000c80e', 'repair_type'::rule_type, '{"allowed": ["ramp", "accessibility"]}'::jsonb, 'Access or bathroom change', 1),
  ('438830d1-72be-5617-8a9c-c5f341d8d76b', 'eb54db11-f9f7-5395-a7fc-37cd6000c80e', 'external_verification'::rule_type, '{"message": "Needs a prescription from a VA physician showing the change is medically necessary."}'::jsonb, 'VA prescription', 2),
  ('ac4156c8-835d-568e-81e0-39aaaa70aa4d', '4f0df00b-70d0-5e86-9988-7c8de7c0fda1', 'homeowner_status'::rule_type, '{"mode": "all", "checks": [{"field": "is_veteran", "op": "is_true"}, {"field": "va_service_connected", "op": "is_true"}], "fail_message": "For veterans with a service-connected disability only", "unknown_message": "Ask whether the veteran has a service-connected disability rating."}'::jsonb, 'Veteran with a service-connected disability', 0),
  ('2e229d2d-97b4-59d2-95ac-dd636dce4d0a', '4f0df00b-70d0-5e86-9988-7c8de7c0fda1', 'repair_type'::rule_type, '{"allowed": ["ramp", "accessibility", "structural"]}'::jsonb, 'Adaptation for disability', 1),
  ('f8dff0a0-153b-5c29-b13b-8364bb607cae', '4f0df00b-70d0-5e86-9988-7c8de7c0fda1', 'external_verification'::rule_type, '{"message": "Only specific severe disabilities qualify; VA decides from the veteran''s rating."}'::jsonb, 'Qualifying disability', 2),
  ('c4b9fed0-5622-5435-9985-f5aeb0facaf1', '66e2821e-8a1b-5a29-bedc-209de649b79a', 'geographic_scope'::rule_type, '{"scope_level": "state", "allowed_values": ["IN"]}'::jsonb, 'Home is in Indiana', 0),
  ('117c5232-3309-5091-ad18-7f5b1993a89f', '66e2821e-8a1b-5a29-bedc-209de649b79a', 'homeowner_status'::rule_type, '{"mode": "all", "checks": [{"field": "age_oldest_owner", "op": "gte", "value": 60}], "fail_message": "For people age 60 and older", "unknown_message": "Owner''s age not recorded."}'::jsonb, 'Age 60 or older', 1),
